import { BindingMode } from '@antimatterjs/react';
import * as React from 'react';

import { FrameworkElement, IFrameworkElementProps, IFrameworkElementState } from '../FrameworkElement';
import { Panel } from './Panel';
import { ISelectableItemProps, ISelectorProps, ISelectorState, Selector } from './Primitives/Selector';

export interface IListBoxProps extends ISelectorProps
{
}

export interface IListBoxState extends ISelectorState
{
}

export class ListBox extends Selector<IListBoxProps, IListBoxState>
{
    public static DefaultBindings = {
        ItemsSource: {
            NotifyCollectionChanged: true,
            FallbackValue: []
        },
        SelectedItem: {
            Mode: BindingMode.TwoWay
        }
    };

    protected /* override */ GetContainerForItemOverride(): typeof FrameworkElement
    {
        return ListBoxItem;
    }
}

interface IListBoxItemProps extends ISelectableItemProps
{    
}

interface IListBoxItemState extends IFrameworkElementState
{
}

class ListBoxItem<P extends IListBoxItemProps = {}, S extends IListBoxItemState = {}>
    extends Panel<P, S>
{    
    protected /* override */ constructClasses()
    {
        return super.constructClasses() +
            (this.props.IsSelected ? "" : "");
    }

    protected /* override */ getCSSStyles() : React.CSSProperties
    {
        let css: React.CSSProperties = super.getCSSStyles();
        css.margin = "0px";
        if (this.props.IsSelected)
        {
            css.background = "#202080";
            css.color = "White";
        }
        
        return css;
    }

    protected /* override */ renderElement(): JSX.Element
    {
        return super.renderElement();
    }
}